      "tipo": "DrawCalls",
      "causa_raiz": "Explosão severa de chamadas de desenho (Draw Calls atingindo 20.492 contra o limite de 2.579), sobrecarregando a GPU (43.89 ms). Ocorre devido a múltiplos objetos individuais sem Dynamic/Static Batching, materiais duplicados sem GPU Instancing ou falta de Occlusion Culling.",
      "codigo_refatorado": "using UnityEngine;

public class BatchedInstanceManager : MonoBehaviour
{
    [Header("Configurações de Instanciamento")]
    [SerializeField] private Mesh targetMesh;
    [SerializeField] private Material targetMaterial;
    [SerializeField] private Transform[] spawnPoints;

    private Matrix4x4[][] batches;
    private MaterialPropertyBlock propBlock;
    private const int BATCH_SIZE = 1023;

    private void Awake()
    {
        if (targetMesh == null || targetMaterial == null || spawnPoints == null || spawnPoints.Length == 0)
            return;

        propBlock = new MaterialPropertyBlock();
        int totalCount = spawnPoints.Length;
        int batchCount = Mathf.CeilToInt((float)totalCount / BATCH_SIZE);
        batches = new Matrix4x4[batchCount][];

        for (int b = 0; b < batchCount; b++)
        {
            int currentSize = Mathf.Min(BATCH_SIZE, totalCount - b * BATCH_SIZE);
            batches[b] = new Matrix4x4[currentSize];
            for (int i = 0; i < currentSize; i++)
            {
                int idx = b * BATCH_SIZE + i;
                batches[b][i] = Matrix4x4.TRS(spawnPoints[idx].position, spawnPoints[idx].rotation, spawnPoints[idx].localScale);
            }
        }
    }

    private void Update()
    {
        if (batches == null || targetMesh == null || targetMaterial == null)
            return;

        for (int i = 0; i < batches.Length; i++)
        {
            Graphics.DrawMeshInstanced(targetMesh, 0, targetMaterial, batches[i], batches[i].Length, propBlock);
        }
    }
}",
      "explicacao_didatica": "Draw Call é a ordem que a CPU envia para a placa de vídeo desenhar um objeto na tela. Seu jogo estava enviando mais de 20 mil ordens separadas por quadro, travando a placa de vídeo. Usando GPU Instancing através da função Graphics.DrawMeshInstanced, empacotamos até 1023 objetos idênticos em uma única chamada de desenho, reduzindo milhares de requisições para poucas dúzias sem perder qualidade."
    }
  ],
  "dicas_level_design": "1. Habilite 'Static' em todos os elementos estáticos do cenário e verifique 'Static Batching' no Project Settings. 2. Gere o 'Occlusion Culling' (Window > Rendering > Occlusion Culling) para impedir a renderização de objetos ocultos atrás de paredes e terreno. 3. Configure LOD Groups (Level of Detail) com distâncias de corte agressivas para desativar malhas distantes. 4. Crie Atlas de Texturas unificando texturas em um único material, permitindo que objetos diferentes compartilhem o mesmo shader/material. 5. Em materiais que suportam, ative a opção 'Enable GPU Instancing' no Inspector."
}

